def record(id,protocol,indication,trial,title,year,pmid,doi,design,population,intervention,comparator,endpoint,timepoint,findings,limitations,url,relation='Protocol defining evidence'):
 r={'evidence_id':id,'protocol_id':protocol,'indication_id':indication,'trial_acronym':trial,'publication_title':title,'year':year,'pmid':pmid,'doi':doi,'publication_url':url,'evidence_context':'Advanced melanoma' if indication=='00431a' else 'Advanced cutaneous squamous-cell carcinoma','study_design':design,'trial_population':population,'intervention':intervention,'comparator':comparator,'primary_endpoint':endpoint,'analysis_timepoint':timepoint,'key_findings':findings,'limitations':limitations,'evidence_relationship':relation,'review_status':'Primary sources reconciled; independent consultant and oncology pharmacy review pending','source_checked_date':checked,'independent_clinical_approval':False,'oncology_pharmacy_approval':False}
 records.append(r)
