# Human-readable spacing throughout narrative only; keep IDs, URLs, PMIDs, DOI intact.
import re
skip={'evidence_id','protocol_id','indication_id','pmid','doi','publication_url','url'}
def fmt(x,k=''):
 if isinstance(x,dict):return {kk:fmt(v,kk) for kk,v in x.items()}
 if isinstance(x,list):return [fmt(v,k) for v in x]
 if isinstance(x,str) and k not in skip:
  x=re.sub(r'(?<=[A-Za-z])(?=\d)', ' ', x)
  x=re.sub(r'(?<=\d)(?=[A-Za-z])', ' ', x)
 return x
